#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Provisioning wizard for Mustang Housing Match (issue #14): the two free commute keys, the AWS backend via
# Amplify sandbox, the invitation landing page, and a live build. Re-runnable; Enter keeps saved values.

TOTAL_STAGES=7
banner "Mustang Housing Match: provision keys and backend"

stage "openrouteservice key (geocoding, walk, bike, drive)"
say "Free Standard plan, no card. One account per person."
open_url "https://account.heigit.org/signup"
step "Sign up (or sign in), then open the Dashboard."
step "Under API keys / Tokens, create a token for this project and copy it."
note "Quota: 2,000 directions and 1,000 geocodes per day, per key. The key ships in the extension bundle by design."
ask_secret VITE_ORS_API_KEY "Paste the openrouteservice key:"
write_env VITE_ORS_API_KEY "$VITE_ORS_API_KEY"

stage "Transitland Routing API key (bus times)"
say "Beta plan, free, 1,000 routing queries per month."
open_url "https://www.transit.land/documentation/routing-api/"
step "Follow the sign-up link: create an Interline account and choose the plan 'Transitland Routing API - Beta'."
step "Open your Interline account page and copy the API key."
ask_secret VITE_TRANSITLAND_API_KEY "Paste the Transitland API key:"
write_env VITE_TRANSITLAND_API_KEY "$VITE_TRANSITLAND_API_KEY"
write_env VITE_COMMUTE_PROVIDER "live"

stage "AWS account and Amplify deploy profile"
say "The backend deploys from this laptop with your own AWS account."
open_url "https://docs.amplify.aws/react/start/account-setup/"
step "Follow 'Configure AWS for local development': enable IAM Identity Center, create user 'amplify-admin' with the"
step "AmplifyBackendDeployFullAccess permission set, then run in another terminal:  aws configure sso"
step "Name the profile when asked; note the Region you chose (us-west-2 is closest to SLO)."
ask AWS_PROFILE "AWS CLI profile name [amplify-admin]:"
AWS_PROFILE="${AWS_PROFILE:-amplify-admin}"
ask AWS_REGION "AWS Region [us-west-2]:"
AWS_REGION="${AWS_REGION:-us-west-2}"
write_env AWS_PROFILE "$AWS_PROFILE"
write_env AWS_REGION "$AWS_REGION"
write_env AMPLIFY_SANDBOX_IDENTIFIER "pilot"

stage "Deploy the Shared List backend (Amplify sandbox 'pilot')"
say "This creates AppSync, DynamoDB, a Cognito identity pool and IAM roles in your account. Cost at pilot scale rounds to zero."
warn "Never run 'npx ampx sandbox delete --identifier pilot' while roommates are using the pilot."
if confirm "Run  npx ampx sandbox --identifier pilot --once --outputs-out-dir ./config  now?"; then
  mkdir -p config
  AWS_PROFILE="$AWS_PROFILE" AWS_REGION="$AWS_REGION" npx ampx sandbox --identifier pilot --once --outputs-out-dir ./config
  if [[ -f config/amplify_outputs.json ]]; then
    region=$(node -e "const o=require('./config/amplify_outputs.json');process.stdout.write(o.custom.sharedListApi.region||o.auth.aws_region||'')")
    pool=$(node -e "const o=require('./config/amplify_outputs.json');process.stdout.write(o.auth.identity_pool_id||'')")
    url=$(node -e "const o=require('./config/amplify_outputs.json');process.stdout.write(o.custom.sharedListApi.url||'')")
    write_env VITE_AWS_REGION "$region"
    write_env VITE_COGNITO_IDENTITY_POOL_ID "$pool"
    write_env VITE_APPSYNC_GRAPHQL_ENDPOINT "$url"
    write_env VITE_APPSYNC_AUTH_MODE "identityPool"
    write_env VITE_SHARING_PROVIDER "appsync"
  else
    warn "config/amplify_outputs.json not found; the deploy did not finish."
    SKIPPED+=("Amplify sandbox deploy (re-run this wizard or: npx ampx sandbox --identifier pilot --once --outputs-out-dir ./config)")
  fi
else
  note "If the Region is not bootstrapped, the first run asks you to open the Amplify console and choose 'Initialize setup now', then re-run."
  SKIPPED+=("Amplify sandbox deploy and the four VITE_ backend values")
fi

stage "Invitation landing page (GitHub Pages)"
say "Invitation Links point at a static page in this repo's docs/join/ folder."
open_url "https://github.com/aabro1325/mustang-housing-match/settings/pages"
step "Build and deployment → Source: 'Deploy from a branch' → Branch: main, folder: /docs → Save."
step "Wait for the green check; the page will be at https://aabro1325.github.io/mustang-housing-match/join/"
ask VITE_INVITE_LINK_BASE "Invitation link base [https://aabro1325.github.io/mustang-housing-match/join/]:"
VITE_INVITE_LINK_BASE="${VITE_INVITE_LINK_BASE:-https://aabro1325.github.io/mustang-housing-match/join/}"
write_env VITE_INVITE_LINK_BASE "$VITE_INVITE_LINK_BASE"

stage "Build the live extension"
if confirm "Run  npm run build  with the live providers now?"; then
  npm run build
  say "dist/ is the unpacked extension."
else
  SKIPPED+=("npm run build")
fi

stage "Load it in Chrome and smoke-test"
open_url "chrome://extensions"
step "Enable Developer mode → Load unpacked → choose the dist/ folder → click the toolbar icon."
step "Set preferences, open a Zillow listing, Analyze, confirm the Commute section shows live times with attribution."
step "Roommates tab: create a list, copy the invitation link, open it in a second Chrome profile and join."
note "Record where secrets live: .env on this laptop (git-ignored); the AWS stack is 'amplify-mustang-housing-match-pilot-sandbox-*'."
pause "Done?"

finish
